(()=>{const slides=[...document.querySelectorAll('.campaign-slide')];if(!slides.length)return;const counter=document.querySelector('#campaign-count'),pause=document.querySelector('#campaign-pause');const motion=matchMedia('(prefers-reduced-motion: reduce)');let index=0,paused=motion.matches,timer;function show(n){index=(n+slides.length)%slides.length;slides.forEach((s,i)=>s.classList.toggle('is-current',i===index));counter.textContent=String(index+1).padStart(2,'0')+' / 03';}function schedule(){clearInterval(timer);pause.textContent=paused?'Reproduzir':'Pausar';pause.setAttribute('aria-pressed',String(paused));if(!paused&&!document.hidden)timer=setInterval(()=>show(index+1),7000);}document.querySelector('#campaign-prev').onclick=()=>{show(index-1);schedule();};document.querySelector('#campaign-next').onclick=()=>{show(index+1);schedule();};pause.onclick=()=>{paused=!paused;schedule();};document.addEventListener('visibilitychange',schedule);motion.addEventListener('change',()=>{paused=motion.matches;schedule();});schedule();})();